var i=`1394-lamingtons`;var a=`world-1394`;var o=`AU`;var n=`oceania`;var r=8;var s=105;var l={en:`Lamingtons`,ua:`Ламінгтони`};var d={en:`Lamingtons is a dish from Australia featuring all-purpose flour, chicken egg, baking powder, whole cow milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Ламінгтони, страва кухні країни Австралія з такими основними складниками: пшеничне борошно універсальне, куряче яйце, розпушувач тіста, цільне коров'яче молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:13,i:[[`all-purpose-flour`,280,`g`],[`chicken-egg`,4,`pcs`],[`white-granulated-sugar`,180,`g`],[`unsalted-butter`,70,`g`],[`baking-powder`,12,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 28 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 28 хвилин до готовності.`,t:[`baking`],m:28,i:[]},{en:`Dip the prepared pieces into the melted coating and let excess drip off; chill until set.`,ua:`Занурте підготовлені шматочки в розтоплене покриття, дайте стекти надлишку й охолодіть до застигання.`,t:[`dipping-in-chocolate`],m:10,i:[[`dark-chocolate`,240,`g`],[`whole-cow-milk`,160,`ml`]]},{en:`Roll the chocolate-dipped sponge squares in dry desiccated coconut on all sides and allow the icing to set.`,ua:`Обкачайте з усіх боків бісквітні кубики, змочені шоколадом, у сухій кокосовій стружці й дайте глазурі застигнути.`,t:[`standard-breading`],m:9,i:[[`desiccated-coconut`,270,`g`]]},{en:`Refrigerate the prepared mixture for about 45 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 45 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:45,i:[]}];var c={slug:i,id:a,country:`AU`,region:n,servings:8,minutes:105,title:l,text:d,steps:u};export{o as country,c as default,a as id,s as minutes,n as region,r as servings,i as slug,u as steps,d as text,l as title};